const body = $input.first().json.body ?? $input.first().json;
const { phone, meta_template_name, meta_language, parameters, alert_instance_id, performed_by } = body || {};

if (!meta_template_name || typeof meta_template_name !== 'string') throw new Error('meta_template_name is required');
if (!meta_language || typeof meta_language !== 'string') throw new Error('meta_language is required');
if (parameters !== undefined && !Array.isArray(parameters)) throw new Error('parameters must be an array');
if (alert_instance_id !== undefined && alert_instance_id !== null && !performed_by) throw new Error('performed_by is required when alert_instance_id is provided');

const rawPhone = String(phone ?? '').trim();
const E164 = /^\+[1-9]\d{7,14}$/;
if (!E164.test(rawPhone)) {
  return [{ json: { __error: true, code: 400, message: `Invalid phone number (expected E.164, e.g. +5215512345678): ${phone}` } }];
}

const esc = (value) => String(value).replace(/'/g, "''");
const params = (parameters || []).map((p) => String(p ?? ''));

return [{ json: {
  phone: rawPhone,
  meta_template_name: String(meta_template_name).trim(),
  meta_language: String(meta_language).trim(),
  meta_template_name_sql: esc(String(meta_template_name).trim()),
  meta_language_sql: esc(String(meta_language).trim()),
  parameters: params,
  alert_instance_id: (alert_instance_id !== undefined && alert_instance_id !== null) ? Number(alert_instance_id) : null,
  performed_by: performed_by ? String(performed_by) : null,
} }];

const input = $('Parse & Validate Input').first().json;
const rows = $input.all().map(i => i.json).filter(r => r.id);

if (rows.length === 0) {
  return [{ json: { __error: true, code: 404, message: `No WHATSAPP template found for meta_template_name="${input.meta_template_name}" and meta_language="${input.meta_language}"` } }];
}

const template = rows[0];

if (template.meta_status !== 'APPROVED') {
  return [{ json: { __error: true, code: 409, message: `Template "${input.meta_template_name}" is not approved yet (status: ${template.meta_status || 'PENDING'})` } }];
}

let expectedCount = null;
try {
  const schema = typeof template.variables_schema === 'string' ? JSON.parse(template.variables_schema) : template.variables_schema;
  if (Array.isArray(schema)) expectedCount = schema.length;
} catch {
  expectedCount = null;
}

if (expectedCount !== null && input.parameters.length !== expectedCount) {
  return [{ json: { __error: true, code: 400, message: `Expected ${expectedCount} template parameters, received ${input.parameters.length}` } }];
}

return [{ json: {
  ...input,
  template_code: template.code,
} }];

const input = $('Validate Template & Params').first().json;
const res = $input.first().json;
const statusCode = res.statusCode;
const respBody = res.body || {};

if (statusCode >= 200 && statusCode < 300) {
  const messageId = respBody?.messages?.[0]?.id || respBody?.id || null;
  const actionData = {
    phone: input.phone,
    meta_template_name: input.meta_template_name,
    template_code: input.template_code,
    parameters: input.parameters,
    message_id: messageId,
  };
  const esc = (value) => String(value).replace(/'/g, "''");
  return [{ json: {
    ...input,
    success: true,
    message_id: messageId,
    ycloud_status: respBody?.messages?.[0]?.status || 'sent',
    action_data_sql: esc(JSON.stringify(actionData)),
  } }];
}

const errMessage = respBody?.error?.message || respBody?.message || JSON.stringify(respBody);
return [{ json: { __error: true, code: 502, message: `YCloud rejected the message: ${errMessage}` } }];

const d = $input.first().json;
return [{ json: {
  success: true,
  code: 200,
  message_id: d.message_id,
  status: d.ycloud_status,
  to: d.phone,
  meta_template_name: d.meta_template_name,
  template_code: d.template_code,
} }];
